pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // 1. Restrict admissible domain: arrays must be non-empty and have matching lengths.
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Ensure the external call target is a contract that does not revert.
        // We deploy a minimal helper that accepts the transferFrom call without reverting.
        Passer passer = new Passer();
        caddress = address(passer);

        // 2. Execute transfer. Since the helper never reverts, the call should succeed.
        bool result = c.transfer(from, caddress, _tos, v);

        // 3. Assert: the return value must be true for a successful non-reverting call.
        assertTrue(result);
    }
}

contract Passer {
    // Matches transferFrom(address,address,uint256) signature.
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

