pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256[] calldata v) public {
        // 1. Restrict to admissible domain: arrays non-empty and lengths match
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // 2. Deploy a helper that always returns true on transferFrom calls, so it never reverts
        MockToken token = new MockToken();
        // Use the helper as the caddress
        // 3. assert that a non-reverting call returns true
        bool success;
        try c.transfer(from, address(token), _tos, v) returns (bool result) {
            success = true;
            assertTrue(result);
        } catch {
            // Reverting is also admissible, but we only care about non-reverting paths
            success = false;
        }
    }
}

contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

