pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // Assume arrays are equal length and non-empty to satisfy require
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Wrap the call to catch reverts
        (bool success, bytes memory retdata) = address(c).call(
            abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, caddress, _tos, v)
        );

        // If the call did not revert, we assert on the returned bool
        if (success) {
            bool returned = abi.decode(retdata, (bool));
            assertTrue(returned);
        }
    }
}

