pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address payable recipient, address[] memory _tos, uint[] memory v) public {
        vm.assume(from != address(0) && recipient != address(0));
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(v[i] > 0);
        }
        // Deploy a helper that always accepts calls so the low-level .call succeeds
        Callee helper = new Callee();
        bool ok;
        try c.transfer(from, address(helper), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = true; // revert is not the property we check here
        }
        assertTrue(ok);
    }
}

contract Callee {
    fallback() external payable { }
}
